// Seeds the form-definition + rule tables from prisma/seed/form-definition.json
// (generated by prisma/seed/extract_form_definition.py from the spec workbook).
// Idempotent: clears the definition tables and recreates them. Participant data
// (observations etc.) is never touched.
//
// Run via:  npx prisma db seed        (configured in prisma.config.ts)
// Or:       node prisma/seed.mjs
import "dotenv/config";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { PrismaClient, Prisma } from "@prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import bcrypt from "bcryptjs";
import { applyLoerV7Alignment } from "./seed/loer-v7-alignment.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const data = JSON.parse(
  readFileSync(join(__dirname, "seed", "form-definition.json"), "utf-8"),
);
let translations = {};
try {
  translations = JSON.parse(
    readFileSync(join(__dirname, "seed", "translations.json"), "utf-8"),
  );
} catch (e) {
  console.warn("Could not load translations.json, using empty dictionary:", e.message);
}

let additionalTranslations = {};
try {
  additionalTranslations = JSON.parse(
    readFileSync(join(__dirname, "seed", "translations-luo-kik.json"), "utf-8"),
  );
} catch (e) {
  console.warn("Could not load translations-luo-kik.json, using empty dictionary:", e.message);
}

// Wizard chrome (nav buttons, safety banner) — `UI.` keys, see src/lib/observation/ui-strings.ts.
let uiTranslations = {};
try {
  uiTranslations = JSON.parse(
    readFileSync(join(__dirname, "seed", "translations-ui.json"), "utf-8"),
  );
} catch (e) {
  console.warn("Could not load translations-ui.json, using empty dictionary:", e.message);
}

const url = process.env.DATABASE_URL || "postgresql://his_test:his_test@127.0.0.1:5432/wombatlas_db?schema=public";
const parsed = new URL(url);
const adapter = new PrismaPg({
  connectionString: url,
});
const prisma = new PrismaClient({ adapter });

const json = (v) => (v == null ? Prisma.DbNull : v);

async function seedAdmin() {
  const email = "admin@system.com";
  // 10 salt rounds matches src/actions/admin.ts.
  const password = await bcrypt.hash("password", 10);

  const admin = await prisma.user.upsert({
    where: { email },
    update: { role: "admin", password },
    create: { email, name: "System Admin", role: "admin", password },
  });

  console.log(`Seeded admin user: ${admin.email} (id: ${admin.id})`);
}

async function seedParticipant() {
  const email = "participant@system.com";
  const password = await bcrypt.hash("password", 10);

  const participant = await prisma.user.upsert({
    where: { email },
    update: { role: "participant", password },
    create: { email, name: "Test Participant", role: "participant", password },
  });

  console.log(`Seeded participant user: ${participant.email} (id: ${participant.id})`);
}

async function main() {
  console.log("Seeding users...");
  await seedAdmin();
  await seedParticipant();

  // Realign the generated (mobile-register) flow to LOER v7.0.0 before writing.
  // In-memory only: prisma/seed/form-definition.json is left untouched, so
  // `npm run form:build` and this overlay stay independent.
  const loer = applyLoerV7Alignment(data);
  console.log(
    `LOER v7 alignment: +${loer.screens} screens (RETRO retired: ${loer.retired}), ` +
      `+${loer.questions} questions (+${loer.options} options, +${loer.prompts} prompts), ` +
      `${loer.unprojected} unprojected, ${loer.routes} routes.`,
  );


  console.log("Clearing existing form-definition rows...");
  await prisma.reflectionRule.deleteMany();
  await prisma.signalRule.deleteMany();
  await prisma.formFlow.deleteMany(); // cascades -> screens -> questions/options/prompts/routes

  console.log("Seeding flows...");
  for (const f of data.flows) {
    await prisma.formFlow.create({ data: { key: f.key, name: f.name } });
  }

  console.log(`Seeding ${data.screens.length} screens...`);
  for (const s of data.screens) {
    await prisma.formScreen.create({
      data: {
        screenId: s.screenId,
        flowKey: s.flowKey,
        name: s.name,
        section: s.section,
        purpose: s.purpose,
        inputType: s.inputType,
        renderKind: s.renderKind,
        primaryActionLabel: s.primaryActionLabel,
        order: s.order,
        atlasDomain: s.atlasDomain ?? null,
        mvpPhase: s.mvpPhase,
        status: s.status,
        visibilityRule: json(s.visibilityRule),
      },
    });
  }

  console.log(`Seeding ${data.questions.length} questions + options...`);
  for (const q of data.questions) {
    await prisma.formQuestion.create({
      data: {
        fieldId: q.fieldId,
        // AIKB registry field id (snake_case). Verified 1:1 with lowercase(fieldId).
        registryFieldId: q.registryFieldId ?? q.fieldId.toLowerCase(),
        screenId: q.screenId,
        questionText: q.questionText,
        fieldType: q.fieldType,
        required: q.required,
        validation: q.validation ?? null,
        notes: q.notes ?? null,
        targetTable: q.targetTable,
        targetColumn: q.targetColumn,
        order: q.order,
        options: {
          create: q.options.map((o) => ({
            value: o.value,
            label: o.label,
            order: o.order,
            isExclusive: o.isExclusive,
            signalTag: o.signalTag ?? null,
          })),
        },
      },
    });
  }

  console.log(`Seeding ${data.narrativePrompts.length} narrative prompts...`);
  for (const p of data.narrativePrompts) {
    await prisma.narrativePrompt.create({
      data: {
        promptId: p.promptId,
        screenId: p.screenId,
        promptText: p.promptText,
        captureType: p.captureType,
        order: p.order,
      },
    });
  }

  console.log(`Seeding ${data.routes.length} routes...`);
  for (const r of data.routes) {
    await prisma.screenRoute.create({
      data: {
        fromScreenId: r.fromScreenId,
        toScreenId: r.toScreenId,
        condition: json(r.condition),
        priority: r.priority,
        note: r.note ?? null,
      },
    });
  }

  console.log(`Seeding ${data.signals.length} signal rules...`);
  for (const s of data.signals) {
    await prisma.signalRule.create({
      data: {
        signalId: s.signalId,
        name: s.name,
        domain: s.domain,
        sourceScreen: s.sourceScreen,
        condition: s.condition,
        severity: s.severity,
      },
    });
  }

  console.log(`Seeding ${data.reflectionRules.length} reflection rules...`);
  for (const r of data.reflectionRules) {
    await prisma.reflectionRule.create({
      data: {
        ruleId: r.ruleId,
        condition: r.condition,
        reflectionType: r.reflectionType,
        templateCopy: r.templateCopy,
        targetScreen: r.targetScreen,
        priority: r.priority,
      },
    });
  }

  console.log("Clearing existing translations...");
  await prisma.formTranslationData.deleteMany();
  await prisma.formTranslation.deleteMany();

  console.log("Seeding translations...");
  await seedTranslations(data);
  await seedJsonTranslations(translations);
  await seedJsonTranslations(additionalTranslations);
  await seedJsonTranslations(uiTranslations);

  console.log("Seed complete.");
}

async function seedTranslations(formDefinition) {
  for (const screen of formDefinition.screens) {
    if (screen.translations) {
      for (const [field, localeMap] of Object.entries(screen.translations)) {
        const key = `SCREEN.${screen.screenId}.${field}`;
        const translation = await prisma.formTranslation.upsert({
          where: { key },
          update: {},
          create: { key },
        });
        for (const [locale, value] of Object.entries(localeMap)) {
          await prisma.formTranslationData.upsert({
            where: { translationId_locale: { translationId: translation.id, locale } },
            update: { value },
            create: { translationId: translation.id, locale, value },
          });
        }
      }
    }
  }

  for (const question of formDefinition.questions) {
    if (question.translations) {
      for (const [field, localeMap] of Object.entries(question.translations)) {
        const key = `QUESTION.${question.fieldId}.${field}`;
        const translation = await prisma.formTranslation.upsert({
          where: { key },
          update: {},
          create: { key },
        });
        for (const [locale, value] of Object.entries(localeMap)) {
          await prisma.formTranslationData.upsert({
            where: { translationId_locale: { translationId: translation.id, locale } },
            update: { value },
            create: { translationId: translation.id, locale, value },
          });
        }
      }
    }

    if (question.options) {
      for (const option of question.options) {
        if (option.translations) {
          for (const [field, localeMap] of Object.entries(option.translations)) {
            const key = `OPTION.${question.fieldId}.${option.value}.${field}`;
            const translation = await prisma.formTranslation.upsert({
              where: { key },
              update: {},
              create: { key },
            });
            for (const [locale, value] of Object.entries(localeMap)) {
              await prisma.formTranslationData.upsert({
                where: { translationId_locale: { translationId: translation.id, locale } },
                update: { value },
                create: { translationId: translation.id, locale, value },
              });
            }
          }
        }
      }
    }
  }

  if (formDefinition.narrativePrompts) {
    for (const prompt of formDefinition.narrativePrompts) {
      if (prompt.translations) {
        for (const [field, localeMap] of Object.entries(prompt.translations)) {
          const key = `PROMPT.${prompt.promptId}.${field}`;
          const translation = await prisma.formTranslation.upsert({
            where: { key },
            update: {},
            create: { key },
          });
          for (const [locale, value] of Object.entries(localeMap)) {
            await prisma.formTranslationData.upsert({
              where: { translationId_locale: { translationId: translation.id, locale } },
              update: { value },
              create: { translationId: translation.id, locale, value },
            });
          }
        }
      }
    }
  }
}

async function seedJsonTranslations(translations) {
  console.log(`Seeding ${Object.keys(translations).length} external translations...`);
  for (const [key, localeMap] of Object.entries(translations)) {
    const translation = await prisma.formTranslation.upsert({
      where: { key },
      update: {},
      create: { key },
    });
    for (const [locale, value] of Object.entries(localeMap)) {
      await prisma.formTranslationData.upsert({
        where: { translationId_locale: { translationId: translation.id, locale } },
        update: { value },
        create: { translationId: translation.id, locale, value },
      });
    }
  }
}


main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
